package de.privacyguard.adhook.imported.shield;
import android.app.Activity;import android.app.AlertDialog;import android.content.Intent;import android.net.Uri;import android.os.Bundle;import android.view.Gravity;import android.widget.*;import java.util.*;
/** Sequential user-confirmed Android uninstaller queue. */
public final class FxYulongBatchCleanupActivity extends Activity{
 private static final int REQUEST=0x59b1;private final ArrayList<String> pkgs=new ArrayList<>(),labels=new ArrayList<>(),reasons=new ArrayList<>();private final Set<String> removed=new HashSet<>();private int index;private TextView state,current;private Button uninstall,next;private int dp(float n){return(int)(n*getResources().getDisplayMetrics().density+0.5f);}
 private TextView t(String s,int z,int c,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);if(bold)v.setTypeface(null,android.graphics.Typeface.BOLD);v.setPadding(dp(4),dp(6),dp(4),dp(6));return v;}
 private Button b(String s,Runnable r){Button x=new Button(this);x.setAllCaps(false);x.setText(s);x.setOnClickListener(v->r.run());return x;}
 @Override protected void onCreate(Bundle saved){super.onCreate(saved);ArrayList<String> p=getIntent().getStringArrayListExtra("packages"),l=getIntent().getStringArrayListExtra("labels"),r=getIntent().getStringArrayListExtra("reasons");if(p!=null&&l!=null&&p.size()==l.size())for(int i=0;i<p.size();i++){String q=p.get(i);if(q==null||!q.matches("[A-Za-z0-9_]+([.][A-Za-z0-9_-]+)+")||pkgs.contains(q))continue;pkgs.add(q);labels.add(l.get(i)==null?q:l.get(i));reasons.add(r!=null&&r.size()>i&&r.get(i)!=null?r.get(i):"");}
 LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xfff7f8fa);LinearLayout h=new LinearLayout(this);h.setGravity(Gravity.CENTER_VERTICAL);h.setPadding(dp(12),dp(8),dp(12),dp(8));h.addView(b("‹ 返回扫描",this::finish));h.addView(t("批量清理 · 逐项确认",19,0xff17212b,true),new LinearLayout.LayoutParams(0,-2,1));root.addView(h);
 ScrollView sc=new ScrollView(this);LinearLayout body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(14),dp(8),dp(14),dp(20));sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));body.addView(t("每项都会打开 Android 系统卸载确认。取消卸载不会自动继续；FX 不会静默卸载、强停或冻结应用。",12,0xff8a5b12,false));state=t("",13,0xff617080,false);current=t("",15,0xff17212b,true);uninstall=b("打开当前应用的系统卸载确认",this::requestCurrent);next=b("跳过当前项，查看下一项",this::advance);body.addView(state);body.addView(current);body.addView(uninstall);body.addView(next);body.addView(b("结束批量处理",this::finish));setContentView(root);render();}
 private boolean installed(String p){try{getPackageManager().getApplicationInfo(p,0);return true;}catch(Throwable e){return false;}}
 private void render(){if(index>=pkgs.size()){state.setText("队列完成。已移除或已不存在 "+removed.size()+" / "+pkgs.size()+" 项。");current.setText("没有剩余项目。");uninstall.setEnabled(false);next.setEnabled(false);return;}String p=pkgs.get(index);state.setText("第 "+(index+1)+" / "+pkgs.size()+" 项 · 已确认移除 "+removed.size()+" 项。");current.setText(labels.get(index)+"\n"+p+"\n"+reasons.get(index));uninstall.setEnabled(installed(p));uninstall.setText(installed(p)?"打开 Android 系统卸载确认":"应用已不存在");next.setEnabled(true);}
 private void requestCurrent(){if(index>=pkgs.size())return;String p=pkgs.get(index);if(!installed(p)){state.setText("应用已不存在，可进入下一项。");return;}new AlertDialog.Builder(this).setTitle("确认打开系统卸载界面").setMessage(labels.get(index)+"\n"+p+"\n\nFX 不会自动点击系统确认按钮。").setNegativeButton("取消",null).setPositiveButton("继续",(d,w)->{try{Intent in=new Intent(Intent.ACTION_DELETE,Uri.parse("package:"+p));in.putExtra(Intent.EXTRA_RETURN_RESULT,true);startActivityForResult(in,REQUEST);}catch(Throwable e){state.setText("无法打开系统卸载界面："+e.getClass().getSimpleName());}}).show();}
 private void advance(){if(index<pkgs.size()){if(!installed(pkgs.get(index)))removed.add(pkgs.get(index));index++;}render();}
 @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode!=REQUEST||index>=pkgs.size())return;String p=pkgs.get(index);if(!installed(p)){removed.add(p);state.setText("系统已移除当前应用。点击“下一项”继续。");}else if(resultCode==RESULT_OK)state.setText("系统返回成功，但应用仍在清单中；请刷新确认。");else state.setText("卸载未完成或已取消。可重新确认或跳过此项。");uninstall.setEnabled(installed(p));next.setEnabled(true);}
}
